            "childMeaning": "కృష్ణుడు అన్నాడు: 'నువ్వు గొప్ప మాటలు మాట్లాడుతున్నావు, కానీ చిన్న విషయాలకే భయపడుతున్నావు! ప్రాణం ఎప్పటికీ ఉంటుందని తెలిసిన వారు బాధపడరు.'",
